for u in ['AGU','L1d-TLB','Load_Queue']:
    try:
        d = json.load(open(f'runs/lsu/pilot/{u}/unit_status.json'))
        items = d['items']
        comp = sum(1 for v in items.values() if v['status']=='COMPLETE')
        blk = sum(1 for v in items.values() if v['status']=='BLOCKED')
        print(f'{u}: {len(items)} 终态 (C{comp}/B{blk})')
        for k,v in list(items.items())[-3:]:
            print(f\"   {k}: {v['status']} act={v.get('activated_runs')}/{v.get('attempted_runs')}\")
    except FileNotFoundError: print(f'{u}: 未生成')
"; tail -2 /tmp/pilot_wave.log; pgrep -f lsu_unit_pilot >/dev/null && echo "波次存活" || (grep WAVE_DONE /tmp/pilot_wave.log || echo "进程死"); tail -1 $(ls -t runs/lsu/guard/*rsrc.log | head -1) | python3 -c "import json,sys; d=json.load(sys.stdin); print(f'MemAvail={d[\"mem_available_gib\"]}G trip={d[\"trip\"]} warn={d[\"warning\"]}')"; date "+%H:%M:%S"

